import raw from './monitor.json';
import { assertEntry, assertMonitor, displayName } from 'utils/restrictions';
import { InterfaceEntry, InterfaceRow, Level, LEVELS } from 'types/restrictions';

// Generated by `pnpm monitor:build` (monitor/scripts/export.py) from the catalog and the probe store: monitor.json holds one
// row per interface with what the dashboard shows; interfaces/<id>.json holds the whole record of one interface and is
// loaded only when its page opens. The JSON literal types widen to `string`, so both are narrowed by assertMonitor() /
// assertEntry(), which throw on any enum mismatch.
export const dataset = assertMonitor(raw as unknown);

export const interfaces: InterfaceRow[] = dataset.interfaces;

export const interfacesById: Map<string, InterfaceRow> = new Map(interfaces.map((i) => [i.id, i]));

// One lazy chunk per interface file; nothing is downloaded until loadInterface() asks for it.
const detailFiles = import.meta.glob<{ default: unknown }>('./interfaces/*.json');

/** The whole record of one interface, or null when there is no such file. Parsed once, then kept. */
export async function loadInterface(id: string): Promise<InterfaceEntry | null> {
  const load = detailFiles[`./interfaces/${id}.json`];
  if (!load) return null;
  const cached = detailCache.get(id);
  if (cached) return cached;
  const entry = assertEntry((await load()).default);
  detailCache.set(id, entry);
  return entry;
}
const detailCache = new Map<string, InterfaceEntry>();

export const levelCounts: Record<Level, number> = LEVELS.reduce(
  (acc, level) => ({ ...acc, [level]: interfaces.filter((i) => i.level === level).length }),
  {} as Record<Level, number>
);

/** Other versions of the same protocol (same family), current ones first. */
export const versionsOf = (entry: InterfaceRow): InterfaceRow[] =>
  entry.family
    ? interfaces
        .filter((i) => i.family === entry.family && i.id !== entry.id)
        .sort((a, b) => Number(a.lifecycle === 'legacy') - Number(b.lifecycle === 'legacy') || displayName(a).localeCompare(displayName(b)))
    : [];

export const openSourceCount = interfaces.filter((i) => i.frontend_repo !== null).length;

/** Interfaces that have a cp0x permissionless alternative (pi.cp0x.com). */
export const permissionlessCount = interfaces.filter((i) => i.alternatives.length > 0).length;

/** All network names in the dataset, most common first, for the Network filter. */
export const networkOptions: string[] = Array.from(
  interfaces.reduce((acc, i) => {
    i.networks.forEach((n) => acc.set(n, (acc.get(n) ?? 0) + 1));
    return acc;
  }, new Map<string, number>())
)
  .sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]))
  .map(([n]) => n);
